"""Brute-force solvers for Vertex Cover and Clique, from the definitions."""

from __future__ import annotations

from itertools import combinations


def vertex_cover_answer(instance: dict) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    if k >= n:
        return True
    for size in range(0, k + 1):
        for subset in combinations(range(n), size):
            chosen = set(subset)
            if all(u in chosen or v in chosen for u, v in edges):
                return True
    return False


def clique_answer(instance: dict) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    edge_set = {frozenset((u, v)) for u, v in edges}
    for subset in combinations(range(n), k):
        if all(frozenset((u, v)) in edge_set for u, v in combinations(subset, 2)):
            return True
    return False
EOF
